export function translateText(text: string, locale: Locale): string {
  if (text.length > 512) return text
  const repaired = repairMojibake(text)
  const trimmed = repaired.trim()
  if (!trimmed) return repaired
  const frame = trimmed.match(/^(?:Seleccionar frame|Select frame|Выбрать кадр) (\d+)$/)
  if (frame) return repaired.replace(trimmed, locale === 'ru' ? `Выбрать кадр ${frame[1]}` : locale === 'es' ? `Seleccionar frame ${frame[1]}` : `Select frame ${frame[1]}`)
  const key = aliases[trimmed] ?? trimmed
  const direct = extraTranslations[locale]?.[trimmed] ?? (locale === 'ru' ? directRussian[trimmed] : locale === 'en' ? directEnglish[trimmed] : locale === 'fr' ? directFrench[trimmed] : locale === 'it' ? directItalian[trimmed] : undefined)
  const translated = dictionaries[locale][key] ?? direct ?? dictionaries.en[key]
  return translated === undefined ? repaired : repaired.replace(trimmed, translated)
}

export function localizeElement(root: HTMLElement, locale: Locale): void {
  const isUserContent = (node: Node): boolean => !!(node instanceof Element ? node : node.parentElement)?.closest('[data-user-content="true"], .tree-name, .tree-rename, .document-tabs, .asset-card, .pipeline-assets-list, [contenteditable="true"]')
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT)
  const nodes: Text[] = []
  while (walker.nextNode()) {
    const node = walker.currentNode as Text
    if (!isUserContent(node) && !node.parentElement?.matches('style,script')) nodes.push(node)
  }
  for (const node of nodes) { const value = node.nodeValue ?? ''; const translated = translateText(value, locale); if (translated !== value) node.nodeValue = translated }
  for (const element of root.querySelectorAll<HTMLElement>('[aria-label],[title],[placeholder]')) {
    if (isUserContent(element)) continue
    for (const attribute of ['aria-label', 'title', 'placeholder']) { const value = element.getAttribute(attribute); if (value) element.setAttribute(attribute, translateText(value, locale)) }
  }
}

export function useLocale(): [Locale, (locale: Locale) => void] {
  const [locale, setLocale] = useState<Locale>(getStoredLocale)
  useEffect(() => { document.documentElement.lang = locale; try { localStorage.setItem(storageKey, locale) } catch { /* storage unavailable */ } }, [locale])
  const updateLocale = useCallback((next: Locale) => {
    setLocale(next)
    window.dispatchEvent(new CustomEvent('mosaico:locale-change', { detail: next }))
  }, [])
  useEffect(() => {
    const onLocaleChange = (event: Event) => { const next = (event as CustomEvent<Locale>).detail; if (next === 'en' || next === 'es' || next === 'ru' || next === 'fr' || next === 'it') setLocale(next) }
    window.addEventListener('mosaico:locale-change', onLocaleChange)
    return () => window.removeEventListener('mosaico:locale-change', onLocaleChange)
  }, [])
  return [locale, updateLocale]
}

export function getStoredLocale(): Locale {
  try { const saved = localStorage.getItem(storageKey); return saved === 'es' || saved === 'ru' || saved === 'fr' || saved === 'it' ? saved : 'en' } catch { return 'en' }
}
